import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const validId = id => typeof id === 'string' && id.length > 0;

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Expected an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (!job || typeof job !== 'object' || Array.isArray(job) ||
        !validId(job.id) || !Array.isArray(job.deps) ||
        !['pending', 'succeeded', 'failed'].includes(job.state)) {
      throw new Error('Invalid job fields');
    }
    if (jobs.has(job.id)) throw new Error('Duplicate job ID');
    const deps = new Set();
    for (const dep of job.deps) {
      if (!validId(dep) || deps.has(dep)) throw new Error('Invalid or duplicate dependency');
      deps.add(dep);
    }
    jobs.set(job.id, {
      id: job.id, state: job.state, deps: [...deps], children: [],
      remaining: deps.size, causes: new Set(),
    });
  }
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error('Unknown dependency');
      jobs.get(dep).children.push(job.id);
    }
  }

  // A min-heap ensures newly released nodes compete with all queued nodes.
  const queue = [];
  function push(id) {
    let i = queue.length;
    queue.push(id);
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (compare(queue[parent], id) <= 0) break;
      queue[i] = queue[parent];
      i = parent;
    }
    queue[i] = id;
  }
  function pop() {
    const first = queue[0];
    const last = queue.pop();
    if (queue.length) {
      let i = 0;
      while (2 * i + 1 < queue.length) {
        let child = 2 * i + 1;
        if (child + 1 < queue.length && compare(queue[child + 1], queue[child]) < 0) child++;
        if (compare(last, queue[child]) <= 0) break;
        queue[i] = queue[child];
        i = child;
      }
      queue[i] = last;
    }
    return first;
  }

  for (const job of jobs.values()) if (job.remaining === 0) push(job.id);
  const fullOrder = [];
  while (queue.length) {
    const id = pop();
    const job = jobs.get(id);
    fullOrder.push(id);
    for (const childId of job.children) {
      const child = jobs.get(childId);
      // Propagate ancestry regardless of either endpoint's state.
      for (const cause of job.causes) child.causes.add(cause);
      if (job.state === 'failed') child.causes.add(id);
      if (--child.remaining === 0) push(childId);
    }
  }
  if (fullOrder.length !== jobs.size) throw new Error('Dependency cycle');

  const order = [], ready = [], blocked = [];
  for (const id of fullOrder) {
    const job = jobs.get(id);
    if (job.state !== 'pending') continue;
    if (job.causes.size) {
      blocked.push({ id, causes: [...job.causes].sort(compare) });
    } else {
      order.push(id);
      if (job.deps.every(dep => jobs.get(dep).state === 'succeeded')) ready.push(id);
    }
  }
  ready.sort(compare);
  blocked.sort((a, b) => compare(a.id, b.id));
  return { order, ready, blocked };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const plan = planJobs(JSON.parse(readFileSync(process.argv[2], 'utf8')));
    process.stdout.write(JSON.stringify(plan) + '\n');
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('full graph ordering, immutable inputs and literal string IDs', () => {
  const spec = [job('a', ['z']), job('b'), job('z', [], 'succeeded')];
  for (const j of spec) { Object.freeze(j.deps); Object.freeze(j); }
  Object.freeze(spec);
  assert.deepEqual(planJobs(spec), { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] });
  const ids = ['__proto__', 'constructor', 'é', 'Z', 'a', ' ', '😀', '\uE000'];
  const sorted = [...ids].sort();
  assert.deepEqual(planJobs(ids.map(id => job(id))), { order: sorted, ready: sorted, blocked: [] });
  assert.deepEqual(planJobs([job('__proto__', [], 'failed'), job('constructor', ['__proto__'])]), {
    order: [], ready: [], blocked: [{ id: 'constructor', causes: ['__proto__'] }],
  });
});

test('all failed ancestors survive completed intermediates and converging paths', () => {
  const spec = [job('f', [], 'failed'), job('g', ['f'], 'failed'),
    job('s', ['g'], 'succeeded'), job('x', ['f', 's']), job('y', ['x']),
    job('ok', [], 'succeeded'), job('r', ['ok']), job('later', ['r'])];
  assert.deepEqual(planJobs(spec), {
    order: ['r', 'later'], ready: ['r'],
    blocked: [{ id: 'x', causes: ['f', 'g'] }, { id: 'y', causes: ['f', 'g'] }],
  });
  assert.deepEqual(planJobs([...spec].reverse()), planJobs(spec));
});

test('rejects malformed required fields, references and all cycles synchronously', () => {
  const invalid = [null, {}, 'jobs', [null], [[]], [{}],
    [{ id: '', deps: [], state: 'pending' }],
    [{ id: 1, deps: [], state: 'pending' }],
    [{ id: 'a', state: 'pending' }],
    [{ id: 'a', deps: 'b', state: 'pending' }],
    [{ id: 'a', deps: [] }],
    [{ id: 'a', deps: [], state: 'Pending' }],
    [job('a', [''])], [job('a', [2])], [job('a', ['missing'])],
    [job('a'), job('a')], [job('a'), job('b', ['a', 'a'])],
    [job('a', ['a'], 'succeeded')],
    [job('a', ['b'], 'failed'), job('b', ['a'], 'succeeded')]];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
  assert.deepEqual(planJobs([{ ...job('a'), ignored: true }]), { order: ['a'], ready: ['a'], blocked: [] });
});

test('CLI success, failures and side-effect-free import', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));
  const run = args => spawnSync(process.execPath, args, { encoding: 'utf8' });
  try {
    const valid = join(dir, 'valid.json');
    const malformed = join(dir, 'malformed.json');
    const graph = join(dir, 'graph.json');
    writeFileSync(valid, JSON.stringify([job('é')]));
    writeFileSync(malformed, '{');
    writeFileSync(graph, JSON.stringify([job('a', ['a'])]));
    const result = run([cli, valid]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify({ order: ['é'], ready: ['é'], blocked: [] }) + '\n');
    for (const args of [[], [valid, valid], [join(dir, 'missing')], [malformed], [graph], [dir]]) {
      const failure = run([cli, ...args]);
      assert.equal(failure.status, 2);
      assert.equal(failure.stdout, '');
      assert.ok(failure.stderr.length > 0);
    }
    const imported = run(['--input-type=module', '-e', `import ${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)};`]);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

